import{_ as e,o as a,c as t,ag as _}from"./chunks/framework.Ddwm6YJC.js";const m=JSON.parse('{"title":"第三卷 潮汐 · 第49章 调整信","description":"","frontmatter":{},"headers":[],"relativePath":"第49章_调整信.md","filePath":"第49章_调整信.md"}'),r={name:"第49章_调整信.md"};function o(n,p,s,c,i,d){return a(),t("div",null,[...p[0]||(p[0]=[_('<h1 id="第三卷-潮汐-·-第49章-调整信" tabindex="-1">第三卷 潮汐 · 第49章 调整信 <a class="header-anchor" href="#第三卷-潮汐-·-第49章-调整信" aria-label="Permalink to &quot;第三卷 潮汐 · 第49章 调整信&quot;">​</a></h1><p>高二秋冬交界时，雾气比往常更重。早自习还没开始，教室只亮了半边灯，林小满把一封叠得很整齐的信放在我桌角，说有人托她带给我。我一眼认出那是江苒的字，纸角压得很平，边上系了一颗小小的纸星星。</p><p>我把信攥在手心，纸面微凉，指尖能摸到折痕。我没敢立刻打开，心跳慢慢变快。陈默从后门进来，看见我的样子，把书包放下，低声问我怎么了。我摇摇头，说没事，只是忽然有点不敢看。</p><p>上午的课我听得很恍惚，黑板上的字忽远忽近，粉笔灰落在讲台上，带着干燥的气味。风从窗缝挤进来，吹得窗帘轻轻晃动。我把信夹在书页里，偶尔瞥一眼，心里像有潮水在退，又在涨。</p><p>中午我独自去了操场边的老槐树下，那里平时很少有人来。落叶铺了薄薄一层，踩上去有很轻的碎裂声。我坐下来，把信放在膝头，深吸一口气，才慢慢展开。</p><p>江苒在开头写，见字如面。她说这些日子想了许多，夜里睡不着，就把心里的潮翻来覆去地看。她说自己以前太跟着情绪走，开心就靠近，难过就躲开，让身边的人都很累。如今她慢慢调整好了，能规律作息，也能安静看完一整本书。</p><p>她写，沈聿，我知道你把很多期待放在我身上，怕我难过，怕我掉队，怕我独自走夜路。可我希望你把这份心意收回去一些，别把寄托放在别人身上，包括我。一个人若总是望着别人，就容易忘记自己的路。</p><p>看到这里，我眼眶有点发热。风吹过树梢，一片叶子落在我肩头。我把叶子拿下来，捏在指间，叶脉清晰，边缘微卷，带着秋末的凉意。</p><p>她继续写，说这话并非要推开我，恰恰相反，是想走得更近一些。过去我们像两根缠得太紧的线，彼此都喘不过气。如今她想学着松开一点，各自站直，再好好并肩走。她问我，愿不愿意和她重新开始，把以前的别扭翻过去。</p><p>信尾她画了一颗小星星，旁边写着，纸星星给你留着，海盐糖也还有，若是和好，我们就一起分掉。</p><p>我把信纸贴在胸口，闭上眼睛。远处传来上课铃声，悠长干净，操场上空无一人，只有雾气缓缓移动。海水的味道似乎从南雾县方向飘来，咸咸的，带着潮汐的气息。</p><p>下午我找到江苒时，她正和顾远在走廊说话。看见我，她愣了一下，眼里有期待，也有不安。顾远识趣地走开，还拍了拍我的肩膀。</p><p>我说，我看了你的信。她低下头，手指绞着衣角，轻声问，你觉得如何。我说，我起初有点难受，以为你想疏远我。她抬起头，很认真地看着我，说，我想了很久才写下这些，我只是不想你活得那么累。</p><p>走廊很安静，只有风声。阳光透过雾气洒下来，落在她发梢，泛着柔和的光。我闻到她袖口淡淡的皂香，混着纸张的气味。</p><p>我说，江苒，你说得对。这些日子我也在想，我把太多心情寄托在你身上，你开心我就安心，你躲开我就慌乱。这样对你不公平，对我也不好。她点点头，眼圈微红，说，我们太在意对方，反而忘了照顾自己。</p><p>我说，可我想和你一起改。她愣住。我继续说，我也调整了许多，夜里不再翻来覆去想白天的事，早上会早起跑一圈，上课也更专心。我想把自己的路走稳，再陪你走。</p><p>她笑起来，眼里有泪光，说，那我们算同时修好了各自的小船吗。我点头，说，以后潮起潮落，我们都不慌。她伸出手，说，那拉钩。我勾住她的小指晃了晃，指尖温热，心里踏实。</p><p>林小满探出头来，笑着说，你们终于不别扭了。陈默走过来，递给我一颗海盐糖，说，宋阿婆托人带来的，甜得很，适合今天。我剥开糖纸放进嘴里，咸甜交织，慢慢化开。</p><p>江苒从口袋掏出两颗纸星星，一颗放我手心，一颗自己留着。她说，以前叠了许多，都放在旧磁带盒里，如今想一只只送出去，第一只就给你。我把星星举到眼前，光穿过纸缝，透出暖黄的轮廓。</p><p>放学我们沿小路往海堤方向走，脚步落在石板上，有清脆的回声。江苒忽然停下，认真问我，沈聿，若以后我又钻牛角尖，你会如何。我说，我就把这封信拿出来，再读一遍，再陪你走一段。她说好，我也如此对你。</p><p>海风迎面吹来，带着咸味，吹乱她的头发。我伸手帮她把发丝别到耳后，她脸颊微凉，耳朵有点红。我们没再说话，只是并肩站着，看潮水慢慢漫上来，又轻轻退下去。</p><p>临别时，她把信封塞回我手里，说，这封调整信，你要收好，以后若吵架，就拿出来看看。我点头，把信折好，放进口袋。她挥挥手，转身跑开，书包上的挂饰轻轻晃动。</p><p>晚上回到家，我把纸星星放在窗台上，月光洒进来，星星的影子落在墙上，微微晃动。我拿出日记本，笔尖落在纸上，却迟迟没有写。因为我知道，和好才刚刚开始，而潮汐深处，似乎还有一封没拆开的信，正等着我。</p>',23)])])}const f=e(r,[["render",o]]);export{m as __pageData,f as default};
